```go
func findKthNumber(n int, k int) int {
    count := func(cur int64) int64 {
        var res int64 = 0
        nei := cur + 1
        for cur <= int64(n) {
            res += min64(nei, int64(n)+1) - cur
            cur *= 10
            nei *= 10
        }
        return res
    }

    var cur int64 = 1
    var i int64 = 1
    for i < int64(k) {
        steps := count(cur)
        if i+steps <= int64(k) {
            cur++
            i += steps
        } else {
            cur *= 10
            i++
        }
    }
    return int(cur)
}

func min64(a, b int64) int64 {
    if a < b {
        return a
    }
    return b
}
```

```kotlin
class Solution {
    fun findKthNumber(n: Int, k: Int): Int {
        fun count(cur: Long): Long {
            var c = cur
            var nei = cur + 1
            var res = 0L
            while (c <= n) {
                res += minOf(nei, n.toLong() + 1) - c
                c *= 10
                nei *= 10
            }
            return res
        }

        var cur = 1L
        var i = 1L
        while (i < k) {
            val steps = count(cur)
            if (i + steps <= k) {
                cur++
                i += steps
            } else {
                cur *= 10
                i++
            }
        }
        return cur.toInt()
    }
}
```

